<script setup lang="ts">
import {qualityText as qt} from '../shared/i18n'

import {reactive} from 'vue'
import {useConfigurationPage} from '../hooks/useConfigurationPage'
import {time,type Configuration} from '../shared/types'
const props=defineProps<{level:number;special?:string}>(),vm=reactive(useConfigurationPage(props.level,props.special))
</script>
<template><a-card :title="special==='evaluation'?qt('ratingIntervals'):special==='settings'?qt('applicationSettings'):(level===1?qt('company'):qt('project2'))+qt('basicConfiguration')">
 <template #extra><a-space><a-popconfirm v-if="vm.selectedKeys.length&&vm.can('quality-configuration','delete')" :title="qt('deleteSelected')" @confirm="vm.removeSelected"><a-button danger>{{qt('deleteSelected')}}</a-button></a-popconfirm><a-button @click="vm.load" :loading="vm.loading">{{qt('refresh')}}</a-button><a-button v-if="vm.can('quality-configuration','save')" type="primary" @click="vm.edit()">{{qt('add')}}</a-button></a-space></template>
 <a-alert v-if="vm.error" :message="vm.error" type="error" show-icon />
 <a-space wrap style="margin:16px 0"><a-select v-if="level===1&&!special" v-model:value="vm.targetLevel" :options="[{value:1,label:qt('companyConfiguration')},{value:2,label:qt('projectConfiguration')}]" style="width:160px" /><a-select v-if="vm.targetLevel===2" v-model:value="vm.projectId" show-search option-filter-prop="label" :options="vm.projects.map(p=>({value:p.id,label:p.name}))" :placeholder="qt('selectBusinessProject')" style="width:230px" /><a-input-search v-model:value="vm.name" :placeholder="qt('searchByName')" @search="vm.search" /><template v-if="!special"><a-select v-model:value="vm.importTarget" :options="[{value:'subjects',label:qt('importLinesAndSubjects')},{value:'basic',label:qt('importCheckContent')},{value:'task',label:qt('importInspectionConfiguration')}]" style="width:180px" /><a-button @click="vm.downloadTemplate">{{qt('downloadTemplate')}}</a-button><a-upload v-if="vm.can('quality-configuration','save')" :show-upload-list="false" :before-upload="vm.importFile" accept=".xlsx,.xls" :disabled="vm.importing"><a-button :loading="vm.importing">{{qt('importExcel')}}</a-button></a-upload></template></a-space>
 <a-space wrap v-if="!special" style="margin-bottom:16px"><a-select v-if="['subject','content','inspection-content'].includes(vm.kind)" v-model:value="vm.lineIds" mode="multiple" :options="vm.options('line')" :placeholder="qt('inspectionLine')" style="min-width:180px" allow-clear /><a-select v-if="['content','inspection-content'].includes(vm.kind)" v-model:value="vm.subjectIds" mode="multiple" :options="vm.options('subject')" :placeholder="qt('subject')" style="min-width:180px" allow-clear /><a-select v-model:value="vm.filterStatus" :options="[{value:1,label:qt('enabled')},{value:0,label:qt('disabled')}]" :placeholder="qt('status')" style="width:130px" allow-clear /><a-select v-if="vm.kind==='inspection-content'" v-model:value="vm.filterSource" :options="[{value:1,label:qt('companyCreated')},{value:2,label:qt('projectCreated')}]" :placeholder="qt('configurationSource')" style="width:160px" allow-clear /><a-select v-if="vm.kind==='inspection-content'&&vm.targetLevel===1" v-model:value="vm.businessTypeId" :options="vm.options('business-type')" :placeholder="qt('propertyType')" style="width:180px" allow-clear /><a-select v-if="vm.kind==='inspection-content'&&vm.targetLevel===2" v-model:value="vm.frequency" :options="[{value:1,label:qt('daily')},{value:2,label:qt('weekly')},{value:3,label:qt('monthly')}]" :placeholder="qt('inspectionFrequency')" style="width:160px" allow-clear /></a-space>
 <a-tabs v-if="!special" v-model:activeKey="vm.kind"><a-tab-pane v-for="k in vm.configKinds.filter(k=>vm.targetLevel===1||k.value!=='business-type')" :key="k.value" :tab="k.label" /></a-tabs>
 <a-table :locale="level===2&&!vm.projectId?{emptyText:qt('selectBusinessProject')}:{}" :row-selection="{selectedRowKeys:vm.selectedKeys,onChange:(keys:unknown[])=>vm.selectedKeys=keys.map(String),getCheckboxProps:(row:Configuration)=>({disabled:!vm.canMutate(row)})}" :data-source="vm.rows" :loading="vm.loading" row-key="id" :pagination="{current:vm.current,total:vm.total,pageSize:20,showSizeChanger:false}" @change="(p:{current?:number})=>{vm.current=p.current||1;vm.load()}">
 <a-table-column :title="qt('name')" data-index="name" /><a-table-column :title="qt('project')" data-index="projectName" /><a-table-column :title="qt('parent')" key="parent"><template #default="{record}">{{record.data.parentName||'—'}}</template></a-table-column><a-table-column :title="qt('status')" key="status"><template #default="{record}"><a-tag :color="record.status?'green':'default'">{{record.status?qt('enabled'):qt('disabled')}}</a-tag></template></a-table-column>
 <a-table-column v-if="vm.kind==='inspection-content'" :title="qt('points')" key="score"><template #default="{record}">{{record.data.score}}</template></a-table-column><a-table-column v-if="special==='evaluation'" :title="qt('scoreRange')" key="range"><template #default="{record}">{{record.data.minScore}}～{{record.data.maxScore}}</template></a-table-column>
 <a-table-column :title="qt('configurationSource')" key="source"><template #default="{record}">{{record.sourceType===2?qt('projectCreated'):qt('companyCreated')}}</template></a-table-column><a-table-column :title="qt('updated')" key="time"><template #default="{record}">{{time(record.modifyTime)}}</template></a-table-column><a-table-column :title="qt('actions')" key="actions"><template #default="{record}"><a-space><a-button type="link" @click="vm.edit(record,true)">{{qt('details')}}</a-button><a-button v-if="vm.canMutate(record)&&vm.can('quality-configuration','save')" type="link" @click="vm.edit(record)">{{qt('edit')}}</a-button><a-popconfirm v-if="vm.canMutate(record)&&vm.can('quality-configuration','delete')" :title="qt('deleteThisConfiguration')" @confirm="vm.remove(record)"><a-button type="link" danger>{{qt('delete')}}</a-button></a-popconfirm></a-space></template></a-table-column>
 </a-table>
 <a-drawer v-model:open="vm.open" :title="vm.form.id?qt('editConfiguration'):qt('addConfiguration')" width="640" :destroy-on-close="true"><a-form layout="vertical" :model="vm.form" :disabled="vm.viewOnly" @finish="vm.save">
 <a-alert v-if="vm.error" :message="vm.error" type="error" show-icon />
 <a-form-item :label="qt('name')" name="name" :rules="[{required:true,message:qt('enterAName')}]"><a-input v-model:value="vm.form.name" :maxlength="128" /></a-form-item>
 <a-form-item v-if="vm.parentKind" :label="qt('parentConfiguration')" name="parentId" :rules="[{required:true,message:qt('selectAParent')}]"><a-select v-model:value="vm.form.parentId" :options="vm.options(vm.parentKind)" show-search option-filter-prop="label" /></a-form-item>
 <a-form-item v-if="vm.form.kind==='line'" :label="qt('businessSector')"><a-select v-model:value="vm.form.data.categoryId" :options="vm.options('category')" allow-clear /></a-form-item>
 <template v-if="vm.form.kind==='content'"><a-form-item :label="qt('checkRequirements')" :rules="[{required:true}]"><a-textarea v-model:value="vm.form.data.checkContent" :rows="4" /></a-form-item><a-form-item :label="qt('photoRequirements')"><a-textarea v-model:value="vm.form.data.photoRequirement" :rows="2" /></a-form-item><a-form-item :label="qt('points')"><a-input-number v-model:value="vm.form.data.score" :min="0" :max="100" :precision="0" /></a-form-item><a-form-item :label="qt('deductionRule')"><a-textarea v-model:value="vm.form.data.deductionStandard" :rows="3" /></a-form-item></template>
 <template v-if="vm.form.kind==='inspection-content'"><a-form-item :label="qt('checkName')"><a-select v-model:value="vm.form.data.checkContentId" :options="vm.options('content')" show-search option-filter-prop="label" /></a-form-item><a-form-item v-if="vm.targetLevel===1" :label="qt('propertyType')"><a-select v-model:value="vm.form.data.businessTypeId" :options="vm.options('business-type')" allow-clear /></a-form-item><a-form-item :label="qt('points')"><a-input-number v-model:value="vm.form.data.score" :min="0" :max="100" :precision="0" /></a-form-item><a-form-item v-if="vm.targetLevel===2" :label="qt('inspectionFrequency')"><a-select v-model:value="vm.form.data.inspectionFrequency" :options="[{value:1,label:qt('days2')},{value:2,label:qt('weeks')},{value:3,label:qt('months')}]" /></a-form-item><a-form-item :label="qt('deductionRule')"><a-textarea v-model:value="vm.form.data.deductionStandard" :rows="3" /></a-form-item></template>
 <template v-if="special==='evaluation'"><a-form-item :label="qt('minimumScore')"><a-input-number v-model:value="vm.form.data.minScore" :precision="0" /></a-form-item><a-form-item :label="qt('maximumScore')"><a-input-number v-model:value="vm.form.data.maxScore" :precision="0" /></a-form-item></template>
 <a-form-item v-if="special==='settings'" :label="qt('linkedRepairApplication')"><a-input v-model:value="vm.form.data.repairApplicationId" :placeholder="qt('repairApplicationId')" /></a-form-item>
 <a-form-item :label="qt('status')"><a-radio-group v-model:value="vm.form.status"><a-radio :value="1">{{qt('enabled')}}</a-radio><a-radio :value="0">{{qt('disabled')}}</a-radio></a-radio-group></a-form-item><a-form-item :label="qt('sortOrder')"><a-input-number v-model:value="vm.form.sortOrder" :precision="0" /></a-form-item>
 <a-form-item :label="qt('remark')"><a-textarea v-model:value="vm.form.data.remark" /></a-form-item><a-button v-if="!vm.viewOnly" type="primary" html-type="submit" :loading="vm.saving">{{qt('save')}}</a-button></a-form></a-drawer>
 </a-card></template>
